@r2.c4 w.request.constraint request=$r2 on=attribute attribute=drawn.edge value=left words="left edge" operator=eq phase=result

@r1 w.request.request act=make mood=do words="show a big tent three inches in from the left edge" predicate=show
@r1.t w.request.target request=$r1 family=drawn mode=new determiner=indefinite sort=tent
