@r1.c3 w.request.constraint request=$r1 on=attribute attribute=drawn.unit value=inches operator=eq phase=result
@r2 w.request.request act=make mood=do words="a small cat way off on the left"
@r2.t w.request.target request=$r2 family=drawn mode=new determiner=indefinite sort=cat
@r2.c1 w.request.constraint request=$r2 on=size attribute=drawn.size value=small operator=degree phase=result
